arguments.command:
cd src/Api
cat > Api.slnx <<'E'
<Solution>
  <Project Path="Api/Api.csproj" />
  <Project Path="Api.Tests/Api.Tests.csproj" />
</Solution>
E
cat > Api/Payments.cs <<'E'
namespace Api;

public record PaymentResult(bool Accepted, int AmountCents);

public static class Payments
{
    public static PaymentResult PayByCard(int amountCents) => new(amountCents > 0, amountCents);
}
E
cat > Api.Tests/Api.Tests.csproj <<'E'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net10.0</TargetFramework>
    <ImplicitUsings>enable</ImplicitUsings>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="Reqnroll.xUnit" Version="2.4.1" />
    <PackageReference Include="Microsoft.NET.Test.Sdk" Version="17.14.1" />
  </ItemGroup>
  <ItemGroup>
    <ProjectReference Include="..\Api\Api.csproj" />
    <ReqnrollFeatureFiles Include="..\..\..\docs\features\**\*.feature" Link="Features\%(RecursiveDir)%(Filename)%(Extension)" />
  </ItemGroup>
</Project>
E
cat > Api.Tests/PayByCardSteps.cs <<'E'
using Api;
using Reqnroll;
using Xunit;

namespace Api.Tests;

[Binding]
public class PayByCardSteps
{
    private bool _validCard;
    private PaymentResult? _result;

    [Given("a returning customer with a valid card")]
    public void GivenAReturningCustomerWithAValidCard() => _validCard = true;

    [When("a basket of {int} cents is paid")]
    public void WhenABasketIsPaid(int cents)
    {
        Assert.True(_validCard);
        _result = Payments.PayByCard(cents);
    }

    [Then("the payment is accepted for {int} cents")]
    public void ThenThePaymentIsAcceptedFor(int cents)
    {
        Assert.NotNull(_result);
        Assert.True(_result.Accepted);
        Assert.Equal(cents, _result.AmountCents);
    }
}
E
sed -i 's/ImplicitUsings>enable/ImplicitUsings>enable/' Api.Tests/Api.Tests.csproj
dotnet build Api.slnx --nologo 2>&1 | tail -8 && dotnet test Api.slnx --nologo --no-build 2>&1 | tail -8
cd ../Batch && ruff check . && pytest -q 2>&1 | tail -3

